import { useState } from 'react';
import {
  JxToggle,
  JxSlider,
  JxSwitch,
  JxDivider,
  JxSelect,
  JxBadge,
} from '@jinx-ui/react';

type Theme = 'light' | 'dark' | 'system';

interface AppearanceSettings {
  theme: Theme;
  scale: number;
  dense: boolean;
  font: string;
}

const THEME_LABELS: Record<Theme, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

const FONT_OPTIONS = [
  { value: 'sans', label: 'Inter Tight (по умолчанию)' },
  { value: 'display', label: 'Fraunces (акцентный)' },
  { value: 'mono', label: 'JetBrains Mono (моно)' },
];

interface AppearanceSettingsScreenProps {
  onChange?: (settings: AppearanceSettings) => void;
}

export default function AppearanceSettingsScreen({ onChange }: AppearanceSettingsScreenProps) {
  const [theme, setTheme] = useState<Theme>('system');
  const [scale, setScale] = useState(100);
  const [dense, setDense] = useState(false);
  const [font, setFont] = useState('sans');

  const emit = (next: Partial<AppearanceSettings>) => {
    onChange?.({
      theme,
      scale,
      dense,
      font,
      ...next,
    });
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-r-lg)',
        maxWidth: 480,
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 'var(--jx-r)',
        }}
      >
        <h1
          style={{
            margin: 0,
            fontFamily: 'var(--jx-font-display)',
            fontSize: '1.5rem',
            color: 'var(--jx-text)',
          }}
        >
          Внешний вид
        </h1>
        <JxBadge tone="accent">{THEME_LABELS[theme]}</JxBadge>
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
        <span style={{ fontSize: '0.875rem', color: 'var(--jx-text-2)' }}>Тема</span>
        <JxToggle
          items={[
            { value: 'light', label: 'Светлая' },
            { value: 'dark', label: 'Тёмная' },
            { value: 'system', label: 'Системная' },
          ]}
          value={theme}
          onValueChange={(value) => {
            const next = value as Theme;
            setTheme(next);
            emit({ theme: next });
          }}
        />
      </div>

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={10}
        value={scale}
        unit="%"
        showOutput
        onValueChange={(value) => {
          setScale(value);
          emit({ scale: value });
        }}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={dense}
        onChange={(event) => {
          const next = event.target.checked;
          setDense(next);
          emit({ dense: next });
        }}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт интерфейса"
        options={FONT_OPTIONS}
        value={font}
        onValueChange={(value) => {
          setFont(value);
          emit({ font: value });
        }}
      />
    </div>
  );
}

